"use client";
import Image from "next/image";

const Gallery = () => {
    const imagePaths = [
        "/home/img-1.jpg",
        "/home/img-2.jpg",
        "/home/img-3.jpg",
        "/home/img-4.jpg",
        "/home/img-5.jpg",
        "/home/img-6.jpg",
        "/home/img-7.jpg",
        "/home/img-8.jpg",
    ];

    const videoPaths = ["/home/video-01.mp4", "/home/video-02.mp4", "/home/video-03.mp4"];

    return (
        <div className="p-2 md:p-6 lg:p-8 text-center">
            {/* Image Gallery */}
            <h1 className="text-xl md:text-3xl font-bold mb-4 text-[#03133d]">
                Image Gallery
            </h1>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
                {imagePaths.map((src, idx) => (
                    <div
                        key={idx}
                        className="w-full transition-transform hover:scale-105"
                    >
                        <Image
                            src={src}
                            alt={`Gallery ${idx + 1}`}
                            width={300}
                            height={200}
                            className="rounded-md shadow-sm object-cover"
                            quality={75}
                        />
                    </div>
                ))}
            </div>
            {/* Video Gallery */}
            <h1 className="text-xl md:text-3xl font-bold mt-10 mb-4 text-[#03133d]">
                Video Gallery
            </h1>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {videoPaths.map((src, idx) => (
                    <div
                        key={idx}
                        className="w-full transition-transform hover:scale-105"
                    >
                        <video
                            src={src}
                            controls
                            preload="none"
                            className="rounded-md shadow-sm object-cover w-full h-55"
                        />
                    </div>
                ))}
            </div>
        </div>
    );
};
export default Gallery;